(function(root){'use strict';
const labels=['Обычное','Хорошее','Выдающееся','Отличное','Шедевр'];
function points(recipe,levels,data,mastery,math){const id=recipe.id.split('@')[0],contributions=[];for(const [node,bonuses]of Object.entries(data.nodes)){const value=math.level(levels[node],mastery.nodes[node]?.maxLevel||100);if(!value)continue;const coefficient=bonuses.filter(b=>recipe.tier>=b.minTier&&recipe.tier<=b.maxTier&&math.matches(id,b.patterns)).reduce((n,b)=>n+b.coefficient,0);if(coefficient)contributions.push({node,name:mastery.nodes[node]?.name||node,level:value,coefficient,points:value*coefficient});}return {points:contributions.reduce((n,b)=>n+b.points,0),contributions};}
function distribution(bonus,base=[.689,.25,.05,.01,.001]){const rolls=1+Math.floor(Math.max(0,Number(bonus)||0)/100),extra=(Math.max(0,Number(bonus)||0)%100)/100;let cdf=0,prior=0;return base.map(p=>{cdf+=p;const value=(1-extra)*cdf**rolls+extra*cdf**(rolls+1),probability=Math.max(0,value-prior);prior=value;return probability;});}
function allocate(quantity,probabilities){const n=Math.max(0,Math.floor(Number(quantity)||0)),rows=probabilities.map((p,index)=>({index,count:Math.floor(n*p),fraction:n*p-Math.floor(n*p)}));let left=n-rows.reduce((s,r)=>s+r.count,0);for(const r of [...rows].sort((a,b)=>b.fraction-a.fraction||a.index-b.index))if(left-->0)r.count++;return rows.map(r=>r.count);}
function predict(recipe,quantity,cfg,levels,data,mastery,math){if(!recipe.quality)return {valid:false,reason:'У этого предмета нет случайного качества.'};const inherited=(recipe.alternatives?.[Number(cfg.recipeIndex)]?.mats||recipe.mats).some(m=>m.preserveQuality),bonus=points(recipe,levels,data,mastery,math),food=Math.max(0,Number(cfg.qualityFoodBonus)||0),focus=cfg.focus?data.focusBonus:0,total=bonus.points+food+focus,probabilities=inherited?labels.map((_,i)=>i===Number(cfg.quality||1)-1?1:0):distribution(total,data.craftChances),counts=allocate(quantity,probabilities);return {valid:true,inherited,bonus:total,mastery:bonus.points,food,focus,contributions:bonus.contributions,rows:probabilities.map((p,i)=>({quality:i+1,name:labels[i],probability:p,expected:Math.max(0,Number(quantity)||0)*p,count:counts[i]}))};}
function reroll(from,to,itemValue,multiplier,quantity=1,data,overrides={}){from=Number(from)-1;to=Number(to)-1;const n=Math.floor(Number(quantity)),value=Number(itemValue),factor=Number(multiplier);if(Number.isInteger(from)&&Number.isInteger(to)&&from>=0&&from<=4&&to>=0&&to<=4&&to<=from&&Number.isFinite(n)&&n>0)return {valid:true,already:true,quantity:n,attempts:0,totalAttempts:0,unitCost:0,totalCost:0,costs:Array(5).fill(0),visits:Array(5).fill(0),terminal:labels.map((_,i)=>i===from?1:0),rounds:[],limits:{p90:0,p95:0,p99:0}};if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||from>4||to>4||to<0||!Number.isFinite(n)||n<=0||!Number.isFinite(value)||value<=0||!Number.isFinite(factor)||factor<=0)return {valid:false,reason:'Укажите предмет, объём и более высокое целевое качество.'};const costs=labels.map((_,i)=>Number.isFinite(Number(overrides[i+1]))&&Number(overrides[i+1])>0?Number(overrides[i+1]):value*factor*data.rerollModifiers[i]),attempts=Array(5).fill(0),expected=Array(5).fill(0),terminal=Array.from({length:5},()=>Array(5).fill(0));for(let i=to;i<5;i++)terminal[i][i]=1;
 for(let i=to-1;i>=from;i--){const row=data.rerollChances[i],leave=1-row[i];attempts[i]=(1+row.reduce((s,p,j)=>j>i?s+p*attempts[j]:s,0))/leave;expected[i]=(costs[i]+row.reduce((s,p,j)=>j>i?s+p*expected[j]:s,0))/leave;for(let q=to;q<5;q++)terminal[i][q]=row.reduce((s,p,j)=>j>i?s+p*terminal[j][q]:s,0)/leave;}
 let remaining=labels.map((_,i)=>i===from?1:0),rounds=[],sum=1;for(let round=1;round<=10000&&sum>1e-6;round++){let fee=0,next=Array(5).fill(0);for(let i=from;i<to;i++){fee+=remaining[i]*costs[i];for(let j=i;j<to;j++)next[j]+=remaining[i]*data.rerollChances[i][j];}sum=next.reduce((s,p)=>s+p,0);rounds.push({round,success:1-sum,expectedCost:fee});remaining=next;}
 const visits=Array(5).fill(0);for(let i=from;i<to;i++)visits[i]=((i===from?1:0)+visits.reduce((s,v,k)=>k<i?s+v*data.rerollChances[k][i]:s,0))/(1-data.rerollChances[i][i]);
 const confidence=p=>rounds.find(r=>r.success>=p)?.round??null;return {valid:true,quantity:n,attempts:attempts[from],totalAttempts:n*attempts[from],unitCost:expected[from],totalCost:n*expected[from],costs,visits,terminal:terminal[from],rounds,limits:{p90:confidence(.9),p95:confidence(.95),p99:confidence(.99)}};
}
function projection(profit,cycleDays,period,target){const days=Number(period),cycle=Number(cycleDays),enteredGoal=Number(target),goal=Number.isFinite(enteredGoal)&&enteredGoal>0?enteredGoal:null;if(!Number.isFinite(days)||!Number.isFinite(cycle)||!(days>0&&cycle>0))return {valid:false,amount:null,days,goal,progress:null};const amount=Number(profit)*days/cycle,valid=Number.isFinite(amount);return {valid,amount:valid?amount:null,days,goal,progress:valid&&goal!==null?Math.max(0,Math.min(100,amount/goal*100)):null};}
const api={labels,points,distribution,allocate,predict,reroll,projection};root.QualityMath=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
